package com.trampolim.api.education;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.*;
import java.security.*;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class AssessmentService {
    private final JdbcTemplate jdbc;private final LearningAccess access;private final LearningController learning;private final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
    public AssessmentService(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,LearningController learning){this.jdbc=jdbc;this.access=access;this.learning=learning;}
    public record Option(UUID id,String text){}
    public record Question(UUID id,String kind,String text,int points,List<Option> options,UUID correctOptionId,String explanation){}
    public record Competency(UUID id,String name,String description,String skillCode,Integer level){public Competency(UUID id,String name,String description){this(id,name,description,null,null);}}
    @org.springframework.beans.factory.annotation.Autowired(required=false) private com.trampolim.api.radar.RadarBridge radarBridge;
    @org.springframework.beans.factory.annotation.Autowired(required=false) private AdaptiveService adaptive;
    public record Definition(String title,String description,String instructions,String topic,int passPercent,int maxAttempts,Instant dueAt,boolean requireStudy,boolean requiredForCompletion,boolean feedbackEnabled,List<Question> questions,List<Competency> competencies){}
    public record Input(long courseId,Long subjectId,Long moduleId,String status,Integer revision,Definition definition){}
    public record Submission(UUID clientKey,Map<String,String> answers){}
    public record Presentation(boolean highlighted,int sortOrder){}
    @Transactional("capacitaTransactionManager")public void accommodate(String email,long id,AssessmentController.Accommodation input){var teacher=access.teacher(email);var row=assessment(id,true);visible(teacher,row,true);var d=published(row);if(input==null||input.studentEmail()==null||input.extendedDueAt()==null||d.dueAt()==null||!input.extendedDueAt().isAfter(d.dueAt())||!input.extendedDueAt().isAfter(Instant.now()))bad("Informe um prazo futuro posterior ao prazo original de uma avaliação publicada com prazo definido.");var student=access.account(input.studentEmail().trim());jdbc.update("INSERT INTO learning_assessment_accommodations(assessment_id,student_id,extended_due_at,granted_by) VALUES (?,?,?,?) ON CONFLICT(assessment_id,student_id) DO UPDATE SET extended_due_at=EXCLUDED.extended_due_at,granted_by=EXCLUDED.granted_by,updated_at=CURRENT_TIMESTAMP",id,student.id(),java.sql.Timestamp.from(input.extendedDueAt()),teacher.id());audit(teacher.id(),id,null,"ACCOMMODATION_GRANTED");}

    public List<Map<String,Object>> list(String email,boolean manage,Long course,Long module){
        var user=access.account(email);if(manage&&!user.teacher())deny();var args=new ArrayList<Object>();String where=" WHERE TRUE";
        if(manage){if(!user.admin()){where+=" AND c.teacher_id=?";args.add(user.id());}}
        else where+=" AND a.status='PUBLISHED' AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND u.account_status='ACTIVE'";
        if(course!=null){where+=" AND a.course_id=?";args.add(course);}if(module!=null){where+=" AND a.module_id=?";args.add(module);}
        return jdbc.queryForList("SELECT a.id,a.course_id,a.subject_id,a.module_id,a.title,a.topic,a.status,a.revision,c.title AS course_title,m.title AS module_title,u.full_name AS teacher_name FROM learning_assessments a JOIN learning_courses c ON c.id=a.course_id JOIN student_users u ON u.id=c.teacher_id LEFT JOIN learning_modules m ON m.id=a.module_id"+where+" ORDER BY a.id DESC LIMIT 200",args.toArray());
    }
    public Map<String,Object> detail(String email,long id,boolean manage){var user=access.account(email);var row=assessment(id,false);visible(user,row,manage);var result=metadata(row);result.put("definition",manage?definition(row.get("draft")):publicDefinition(published(row)));if(!manage){((Map<String,Object>)result.get("definition")).put("dueAt",effectiveDeadline(published(row),user.id(),id));result.put("attempts",historyFor(user.id(),id));result.put("studyComplete",studyComplete(user.id(),row));}return result;}
    @Transactional("capacitaTransactionManager")public Map<String,Object> create(String email,Input input){var user=access.teacher(email);validate(user,input);long id=jdbc.queryForObject("INSERT INTO learning_assessments(course_id,subject_id,module_id,title,topic,draft) VALUES (?,?,?,?,?,?::jsonb) RETURNING id",Long.class,input.courseId(),input.subjectId(),input.moduleId(),input.definition().title().trim(),text(input.definition().topic(),180),encode(input.definition()));if("PUBLISHED".equals(input.status()))publish(id,input.definition());else jdbc.update("UPDATE learning_assessments SET status=? WHERE id=?",input.status(),id);audit(user.id(),id,null,"CREATED");return Map.of("id",id);}
    @Transactional("capacitaTransactionManager")public void edit(String email,long id,Input input){var user=access.teacher(email);var row=assessment(id,true);visible(user,row,true);validate(user,input);if(((Number)row.get("course_id")).longValue()!=input.courseId()||!Objects.equals(number(row.get("subject_id")),input.subjectId())||!Objects.equals(number(row.get("module_id")),input.moduleId()))bad("O vínculo da avaliação não pode ser alterado. Crie outra avaliação para outro contexto.");if(input.revision()==null||input.revision()!=((Number)row.get("revision")).intValue())conflict("A avaliação mudou. Reabra-a antes de salvar.");jdbc.update("UPDATE learning_assessments SET title=?,topic=?,draft=?::jsonb,status=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.definition().title().trim(),text(input.definition().topic(),180),encode(input.definition()),"PUBLISHED".equals(input.status())?"DRAFT":input.status(),id);if("PUBLISHED".equals(input.status()))publish(id,input.definition());audit(user.id(),id,null,"UPDATED_"+input.status());}
    private void publish(long id,Definition definition){int next=jdbc.queryForObject("SELECT COALESCE(max(version_number),0)+1 FROM learning_assessment_versions WHERE assessment_id=?",Integer.class,id);long version=jdbc.queryForObject("INSERT INTO learning_assessment_versions(assessment_id,version_number,definition) VALUES (?,?,?::jsonb) RETURNING id",Long.class,id,next,encode(definition));jdbc.update("UPDATE learning_assessments SET current_version_id=?,status='PUBLISHED' WHERE id=?",version,id);}

    @Transactional("capacitaTransactionManager")public Map<String,Object> start(String email,long id){
        var user=access.account(email);var row=assessment(id,true);visible(user,row,false);if(adaptive!=null)adaptive.checkPrerequisites(user.id(),number(row.get("module_id")));if(courseOwner(((Number)row.get("course_id")).longValue())==user.id())deny();
        Definition definition=published(row);checkDeadline(definition,user.id(),id);if(definition.requireStudy()&&!studyComplete(user.id(),row))conflict("Conclua as videoaulas deste contexto antes de iniciar a avaliação.");
        var open=jdbc.queryForList("SELECT id FROM learning_assessment_attempts WHERE assessment_id=? AND student_id=? AND status='IN_PROGRESS'",id,user.id());if(!open.isEmpty())return attempt(email,(UUID)open.get(0).get("id"),false);
        int count=jdbc.queryForObject("SELECT count(*) FROM learning_assessment_attempts WHERE assessment_id=? AND student_id=?",Integer.class,id,user.id());if(count>=definition.maxAttempts())conflict("Você atingiu o limite de tentativas desta avaliação.");
        if(jdbc.queryForObject("SELECT count(*) FROM learning_assessment_attempts WHERE student_id=? AND started_at>CURRENT_TIMESTAMP-INTERVAL '1 hour'",Integer.class,user.id())>=20)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Aguarde antes de iniciar outra avaliação.");
        UUID attempt=UUID.randomUUID();jdbc.update("INSERT INTO learning_assessment_attempts(id,assessment_id,version_id,student_id,attempt_number) VALUES (?,?,?,?,?)",attempt,id,row.get("current_version_id"),user.id(),count+1);audit(user.id(),id,attempt,"STARTED");return attempt(email,attempt,false);
    }
    public Map<String,Object> attempt(String email,UUID id,boolean manage){var user=access.account(email);var row=attemptRow(id,false);if(manage)visible(user,assessment(((Number)row.get("assessment_id")).longValue(),false),true);else if(((Number)row.get("student_id")).longValue()!=user.id())deny();Definition definition=definition(row.get("definition"));var result=attemptMetadata(row);if(manage)result.put("definition",definition);else{var visibleDefinition=publicDefinition(definition);visibleDefinition.put("dueAt",effectiveDeadline(definition,user.id(),((Number)row.get("assessment_id")).longValue()));result.put("definition",visibleDefinition);}result.put("answers",decodeMap(row.get("status").equals("SUBMITTED")?row.get("answers"):row.get("draft_answers")));if("SUBMITTED".equals(row.get("status"))&&(manage||definition.feedbackEnabled()))result.put("feedback",feedback(definition,decodeMap(row.get("answers"))));return result;}
    @Transactional("capacitaTransactionManager")public void draft(String email,UUID id,Map<String,String> answers){var user=access.account(email);var row=attemptRow(id,true);ownAttempt(user,row);if(!"IN_PROGRESS".equals(row.get("status")))conflict("Esta tentativa já foi enviada.");var assessment=assessment(((Number)row.get("assessment_id")).longValue(),false);visible(user,assessment,false);checkDeadline(definition(row.get("definition")),user.id(),((Number)row.get("assessment_id")).longValue());validateAnswers(definition(row.get("definition")),answers,false);jdbc.update("UPDATE learning_assessment_attempts SET draft_answers=?::jsonb WHERE id=?",encode(new TreeMap<>(answers)),id);}
    @Transactional("capacitaTransactionManager")public Map<String,Object> submit(String email,UUID id,Submission input){
        var user=access.account(email);if(input==null||input.clientKey()==null||input.answers()==null)bad("Informe as respostas e a identificação do envio.");var row=attemptRow(id,true);ownAttempt(user,row);Definition definition=definition(row.get("definition"));validateAnswers(definition,input.answers(),true);String fingerprint=hash(encode(new TreeMap<>(input.answers())));
        if("SUBMITTED".equals(row.get("status"))){if(!input.clientKey().equals(row.get("submission_key"))||!fingerprint.equals(row.get("request_hash")))conflict("Esta tentativa já foi corrigida e não pode ser alterada.");return attempt(email,id,false);}
        var assessment=assessment(((Number)row.get("assessment_id")).longValue(),false);visible(user,assessment,false);if(adaptive!=null)adaptive.checkPrerequisites(user.id(),number(assessment.get("module_id")));checkDeadline(definition,user.id(),((Number)row.get("assessment_id")).longValue());boolean studied=studyComplete(user.id(),assessment);if(definition.requireStudy()&&!studied)conflict("A conclusão das aulas exigidas ainda não foi comprovada.");
        int total=definition.questions().stream().mapToInt(Question::points).sum(),earned=definition.questions().stream().filter(question->question.correctOptionId().toString().equals(input.answers().get(question.id().toString()))).mapToInt(Question::points).sum();
        BigDecimal score=BigDecimal.valueOf(earned).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(total),2,RoundingMode.HALF_UP);boolean passed=(long)earned*100>=(long)total*definition.passPercent();
        var criteria=Map.of("passPercent",definition.passPercent(),"requireStudy",definition.requireStudy(),"studyCompleteAtSubmission",studied,"maxAttempts",definition.maxAttempts(),"dueAt",definition.dueAt()==null?"":definition.dueAt().toString(),"effectiveDueAt",Objects.toString(effectiveDeadline(definition,user.id(),((Number)row.get("assessment_id")).longValue()),""),"grading","EXACT_SINGLE_CHOICE_WEIGHTED_V1");
        jdbc.update("UPDATE learning_assessment_attempts SET status='SUBMITTED',answers=?::jsonb,draft_answers='{}',submission_key=?,request_hash=?,earned_points=?,total_points=?,score_percent=?,passed=?,criteria=?::jsonb,submitted_at=CURRENT_TIMESTAMP WHERE id=?",encode(new TreeMap<>(input.answers())),input.clientKey(),fingerprint,earned,total,score,passed,encode(criteria),id);
        if(passed&&assessment.get("module_id")!=null){long course=((Number)assessment.get("course_id")).longValue(),module=((Number)assessment.get("module_id")).longValue();var origin=jdbc.queryForMap("SELECT c.title AS course_title,m.title AS module_title,u.full_name AS teacher_name FROM learning_courses c JOIN student_users u ON u.id=c.teacher_id JOIN learning_modules m ON m.id=? WHERE c.id=?",module,course);String criterion="Aprovação na avaliação ‘"+definition.title()+"’: mínimo de "+definition.passPercent()+"%; "+(definition.requireStudy()?"aulas do contexto concluídas (90% de cada vídeo).":"sem exigência adicional de aulas.");for(var competency:definition.competencies())jdbc.update("INSERT INTO learning_competency_awards(id,student_id,assessment_id,attempt_id,competency_key,name,description,course_id,module_id,course_title,module_title,teacher_name,score_percent,criterion,skill_code,skill_level) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT (student_id,assessment_id,competency_key) DO NOTHING",UUID.randomUUID(),user.id(),assessment.get("id"),id,competency.id(),competency.name().trim(),text(competency.description(),2000),course,module,origin.get("course_title"),origin.get("module_title"),origin.get("teacher_name"),score,criterion,competency.skillCode(),competency.level());}
        audit(user.id(),((Number)assessment.get("id")).longValue(),id,passed?"SUBMITTED_PASSED":"SUBMITTED_FAILED");return attempt(email,id,false);
    }
    public List<Map<String,Object>> history(String email){return jdbc.queryForList("SELECT t.id,t.assessment_id,t.attempt_number,t.status,t.earned_points,t.total_points,t.score_percent,t.passed,t.started_at,t.submitted_at,v.definition->>'title' AS title FROM learning_assessment_attempts t JOIN learning_assessment_versions v ON v.id=t.version_id WHERE t.student_id=? ORDER BY t.started_at DESC LIMIT 200",access.account(email).id());}
    public List<Map<String,Object>> report(String email,long id){var user=access.teacher(email);visible(user,assessment(id,false),true);return jdbc.queryForList("SELECT t.id,t.student_id,u.full_name AS student_name,t.attempt_number,t.status,t.earned_points,t.total_points,t.score_percent,t.passed,t.started_at,t.submitted_at FROM learning_assessment_attempts t JOIN student_users u ON u.id=t.student_id WHERE t.assessment_id=? ORDER BY t.started_at DESC LIMIT 200",id);}

    private List<Map<String,Object>> historyFor(long user,long assessment){return jdbc.queryForList("SELECT id,attempt_number,status,earned_points,total_points,score_percent,passed,started_at,submitted_at FROM learning_assessment_attempts WHERE student_id=? AND assessment_id=? ORDER BY attempt_number",user,assessment);}
    private Map<String,Object> assessment(long id,boolean lock){return jdbc.queryForList("SELECT * FROM learning_assessments WHERE id=?"+(lock?" FOR UPDATE":""),id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Avaliação indisponível."));}
    private Map<String,Object> attemptRow(UUID id,boolean lock){return jdbc.queryForList("SELECT t.*,v.definition FROM learning_assessment_attempts t JOIN learning_assessment_versions v ON v.id=t.version_id WHERE t.id=?"+(lock?" FOR UPDATE OF t":""),id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tentativa indisponível."));}
    private void visible(LearningAccess.Account user,Map<String,Object> row,boolean manage){long course=((Number)row.get("course_id")).longValue();if(manage){if(!user.teacher())deny();access.ownCourse(user,course);}else{learning.visibleCourse(user,course,false);if(!"PUBLISHED".equals(row.get("status")))deny();}}
    private void ownAttempt(LearningAccess.Account user,Map<String,Object> row){if(((Number)row.get("student_id")).longValue()!=user.id())deny();}
    private Definition published(Map<String,Object> row){Object id=row.get("current_version_id");if(id==null)conflict("A avaliação ainda não foi publicada.");return definition(jdbc.queryForObject("SELECT definition::text FROM learning_assessment_versions WHERE id=?",String.class,id));}
    private Definition definition(Object value){try{return json.readValue(value.toString(),Definition.class);}catch(Exception error){throw new IllegalStateException("Invalid assessment definition",error);}}
    private Map<String,String> decodeMap(Object value){try{return value==null?Map.of():json.readValue(value.toString(),new com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>(){});}catch(Exception error){throw new IllegalStateException("Invalid stored answers",error);}}
    private Map<String,Object> publicDefinition(Definition d){var result=new LinkedHashMap<String,Object>();result.put("title",d.title());result.put("description",d.description());result.put("instructions",d.instructions());result.put("topic",d.topic());result.put("passPercent",d.passPercent());result.put("maxAttempts",d.maxAttempts());result.put("dueAt",d.dueAt());result.put("requireStudy",d.requireStudy());result.put("requiredForCompletion",d.requiredForCompletion());result.put("competencies",d.competencies());result.put("questions",d.questions().stream().map(q->Map.of("id",q.id(),"kind",q.kind(),"text",q.text(),"points",q.points(),"options",q.options())).toList());return result;}
    private List<Map<String,Object>> feedback(Definition d,Map<String,String> answers){return d.questions().stream().map(q->Map.<String,Object>of("questionId",q.id(),"correct",q.correctOptionId().toString().equals(answers.get(q.id().toString())),"earnedPoints",q.correctOptionId().toString().equals(answers.get(q.id().toString()))?q.points():0,"explanation",text(q.explanation(),2000))).toList();}
    private Map<String,Object> metadata(Map<String,Object> row){var result=new LinkedHashMap<String,Object>();for(String key:List.of("id","course_id","subject_id","module_id","title","topic","status","revision","current_version_id"))result.put(key,row.get(key));return result;}
    private Map<String,Object> attemptMetadata(Map<String,Object> row){var result=new LinkedHashMap<String,Object>();for(String key:List.of("id","assessment_id","version_id","attempt_number","status","earned_points","total_points","score_percent","passed","criteria","started_at","submitted_at"))result.put(key,key.equals("criteria")&&row.get(key)!=null?decodeObject(row.get(key)):row.get(key));return result;}
    private Object decodeObject(Object value){try{return json.readValue(value.toString(),Object.class);}catch(Exception error){throw new IllegalStateException(error);}}
    private Instant effectiveDeadline(Definition d,long student,long assessment){if(d.dueAt()==null)return null;var rows=jdbc.queryForList("SELECT extended_due_at FROM learning_assessment_accommodations WHERE assessment_id=? AND student_id=?",assessment,student);if(rows.isEmpty())return d.dueAt();Instant extended=((java.sql.Timestamp)rows.get(0).get("extended_due_at")).toInstant();return extended.isAfter(d.dueAt())?extended:d.dueAt();}
    private void checkDeadline(Definition d,long student,long assessment){Instant deadline=effectiveDeadline(d,student,assessment);if(deadline!=null&&!deadline.isAfter(Instant.now()))conflict("O prazo desta avaliação terminou. Solicite apoio ao professor caso precise de prazo adicional.");}
    private void validateAnswers(Definition d,Map<String,String> answers,boolean complete){if(answers==null||answers.size()>d.questions().size())bad("Respostas inválidas.");var known=new HashSet<String>();for(Question question:d.questions()){String key=question.id().toString();known.add(key);String chosen=answers.get(key);if(chosen==null){if(complete)bad("Responda todas as questões antes de enviar.");}else if(question.options().stream().noneMatch(option->option.id().toString().equals(chosen)))bad("Alternativa inválida.");}if(!known.containsAll(answers.keySet())||answers.values().stream().anyMatch(Objects::isNull))bad("Respostas desconhecidas.");}
    private void validate(LearningAccess.Account user,Input input){
        if(input==null||input.definition()==null)bad("Informe a avaliação.");access.ownCourse(user,input.courseId());if(!Set.of("DRAFT","PUBLISHED","HIDDEN").contains(Objects.toString(input.status(),"")))bad("Situação inválida.");
        if(input.subjectId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_subjects WHERE id=? AND course_id=?)",Boolean.class,input.subjectId(),input.courseId())))bad("Disciplina de outro curso.");
        if(input.moduleId()!=null&&(access.courseForModule(input.moduleId())!=input.courseId()||input.subjectId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_modules WHERE id=? AND subject_id=?)",Boolean.class,input.moduleId(),input.subjectId()))))bad("Módulo fora do contexto.");
        Definition d=input.definition();required(d.title(),180);text(d.description(),4000);text(d.instructions(),4000);text(d.topic(),180);if(d.passPercent()<1||d.passPercent()>100||d.maxAttempts()<1||d.maxAttempts()>10)bad("Nota mínima entre 1 e 100%; tentativas entre 1 e 10.");
        if(d.questions()==null||d.questions().isEmpty()||d.questions().size()>30||d.competencies()==null||d.competencies().size()>20)bad("Use de 1 a 30 questões e até 20 competências.");
        var ids=new HashSet<UUID>();for(var q:d.questions()){if(q==null||q.id()==null||!ids.add(q.id())||!"MCQ".equals(q.kind())||q.points()<1||q.points()>100||q.options()==null||q.options().size()<2||q.options().size()>6||q.correctOptionId()==null)bad("Questão objetiva inválida.");required(q.text(),2000);text(q.explanation(),2000);var options=new HashSet<UUID>();for(var o:q.options()){if(o==null||o.id()==null||!options.add(o.id()))bad("Alternativas inválidas.");required(o.text(),1000);}if(!options.contains(q.correctOptionId()))bad("Selecione uma resposta correta existente.");}
        var skills=new HashSet<UUID>();for(var c:d.competencies()){if(c==null||c.id()==null||!skills.add(c.id())||input.moduleId()==null)bad("Competências exigem módulo e identificadores únicos.");required(c.name(),180);text(c.description(),2000);if(c.skillCode()!=null&&(!c.skillCode().matches("[a-z][a-z0-9-]{1,63}")||c.level()==null||c.level()<1||c.level()>4)||c.skillCode()==null&&c.level()!=null)bad("Vínculo de competência/nivel inválido.");}
        var canonical=d.competencies().stream().map(Competency::skillCode).filter(Objects::nonNull).distinct().toList();if(!canonical.isEmpty()){if(radarBridge==null)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Catálogo indisponível.");radarBridge.validateSkills(canonical);}
    }
    boolean studyComplete(long student,Map<String,Object> row){String where="s.course_id=?";var args=new ArrayList<Object>();args.add(student);args.add(row.get("course_id"));if(row.get("module_id")!=null){where+=" AND m.id=?";args.add(row.get("module_id"));}else if(row.get("subject_id")!=null){where+=" AND s.id=?";args.add(row.get("subject_id"));}var count=jdbc.queryForMap("SELECT count(*) AS total,count(p.completed_at) AS done FROM learning_lessons l JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id LEFT JOIN learning_lesson_progress p ON p.lesson_id=l.id AND p.student_id=? WHERE "+where+" AND l.status='PUBLISHED' AND l.validation_status='READY'",args.toArray());return ((Number)count.get("total")).longValue()>0&&((Number)count.get("total")).longValue()==((Number)count.get("done")).longValue();}
    private long courseOwner(long course){return jdbc.queryForObject("SELECT teacher_id FROM learning_courses WHERE id=?",Long.class,course);}
    void audit(long actor,Long assessment,UUID resource,String event){jdbc.update("INSERT INTO learning_assessment_audit(actor_id,assessment_id,resource_id,event) VALUES (?,?,?,?)",actor,assessment,resource,event);}
    private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception error){throw new IllegalArgumentException("Invalid data",error);}}
    static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception impossible){throw new IllegalStateException(impossible);}}
    private static Long number(Object value){return value==null?null:((Number)value).longValue();}
    private static String text(String value,int max){if(value==null)return "";if(value.length()>max)bad("Texto acima do limite permitido.");return value.trim();}
    private static void required(String value,int max){if(value==null||value.isBlank())bad("Preencha os campos obrigatórios.");text(value,max);}
    private static void bad(String message){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static void deny(){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Acesso à avaliação não autorizado.");}private static void conflict(String message){throw new ResponseStatusException(HttpStatus.CONFLICT,message);}
}
